    <button class="btn btn-page" disabled="@(CurrentPage <= 1)" @onclick="PreviousPage">
        Previous
    </button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var pageNum = i;
        <button class="btn btn-page @(pageNum == CurrentPage ? "active" : "")"
                @onclick="@(() => GoToPage(pageNum))">
            @pageNum
        </button>
    }

    <button class="btn btn-page" disabled="@(CurrentPage >= TotalPages)" @onclick="NextPage">
        Next
    </button>
